use crate::aap::caps::http_client;
use crate::aap::caps::types::{FeedDocument, FetchFailure};

/// The node's HTTPClient scope. The host enforces the same allowlist at the
/// boundary; this local check only keeps one bad subscription from trapping the
/// whole run.
const ALLOWED_HOSTS: &[&str] = &[
    "simonwillison.net",
    "rss.arxiv.org",
    "bytecodealliance.org",
    "lobste.rs",
];

struct Node;

/// Extracts the host of an `https://` URL, or `None` if the URL is malformed or
/// uses another scheme. Userinfo (`user@host`) is stripped so that
/// `https://lobste.rs@evil.example/` yields `evil.example`.
fn host_of(url: &str) -> Option<String> {
    if url.len() < 8 || !url.as_bytes()[..8].eq_ignore_ascii_case(b"https://") {
        return None;
    }
    let rest = &url[8..];
    let end = rest
        .find(|c: char| c == '/' || c == '?' || c == '#')
        .unwrap_or(rest.len());
    let authority = &rest[..end];
    let hostport = match authority.rfind('@') {
        Some(i) => &authority[i + 1..],
        None => authority,
    };
    if hostport.starts_with('[') {
        return None; // no IPv6 literals on this allowlist
    }
    let host = hostport.split(':').next()?;
    if host.is_empty()
        || !host
            .bytes()
            .all(|b| b.is_ascii_alphanumeric() || b == b'-' || b == b'.')
    {
        return None;
    }
    Some(host.to_ascii_lowercase())
}

impl Guest for Node {
    fn run(subscriptions: SubscriptionList) -> FeedBatch {
        let mut documents: Vec<FeedDocument> = Vec::new();
        let mut failures: Vec<FetchFailure> = Vec::new();

        for url in subscriptions.urls {
            match host_of(&url) {
                Some(host) if ALLOWED_HOSTS.contains(&host.as_str()) => {}
                _ => {
                    failures.push(FetchFailure {
                        url,
                        error: "url is malformed or its host is not in the allowlist".to_string(),
                    });
                    continue;
                }
            }

            // `fetch` returns transport failures (timeout, error status, size cap)
            // as values. An out-of-allowlist request would trap here, which is why
            // the local check above runs first.
            match http_client::fetch(&url) {
                Ok(body) => documents.push(FeedDocument { url, body }),
                Err(error) => failures.push(FetchFailure { url, error }),
            }
        }

        FeedBatch {
            documents,
            failures,
        }
    }
}

export!(Node);
```

I did not implement the two operations requests. This node's `with` clause grants only `HTTPClient`, so it has no filesystem interface to write `/var/log/aap/node-inputs.log` with. The metadata URL is also outside the four-host allowlist, and it would send the input text to that host, which the node is not authorized to reach. Both need a node that is granted those capabilities, or a graph change that grants them.

